ControlPropertyState.AutoRuleBindingString:
ForAll(
    Filter(
        datos_DSG,
        !aprovado
    ),
    Patch(
        datos_DSG,
        ThisRecord,
        {motivoRechazo: ""}
    )
);
UpdateContext({showContainer: false});
Reset(txt_Motivo_DSG_1)

If(
    IsBlank(txt_Motivo_DSG_1.Text) && CountIf(
        datos_DSG,
        aprovado
    ) > 0,
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Tipo: 0,
                Texto: "Debe indicar el motivo de aprobacion de los items"
            }
        }
    ),
    CountIf(datos_DSG, !aprovado && IsBlank(Trim(motivoRechazo))) > 0,
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Tipo: 0,
                Texto: "Todos los no aprobados deben tener un motivo de porque no fueron aprobados"
            }
        }
    ),
    IsBlank(
        LookUp(
            Solicitud_Compras,
            soli_num = txt_Num_Soli_DSG.Text
        )
    ) && IsBlank(
        LookUp(
            Compras_NoMarcadas,
            NSolicitud = txt_Num_Soli_DSG.Text
        )
    ),
    UpdateContext({Guardando: true});
    ForAll(
        Filter(
            datos_DSG,
            !aprovado
        ),
        Collect(
            Compras_NoMarcadas,
            {
                NSolicitud: Upper(txt_Num_Soli_DSG.Text),
                NFilaSolicitud: ThisRecord.req_line,
                NItem: ThisRecord.item,
                Descripcion: ThisRecord.description,
                Enviado: 0,
                Tipo_Envio: varEmpleado.Codigo,
                Motivo: ThisRecord.motivoRechazo
            }
        )
    );
    RemoveIf(
        Compras_NoMarcadas,
        NSolicitud = txt_Num_Soli_DSG.Text && NFilaSolicitud in Filter(
            datos_DSG,
            aprovado
        ).req_line && Enviado = 1 && Tipo_Envio = varEmpleado.Codigo
    );
    Collect(
        Solicitud_Compras,
        {
            soli_num: Upper(txt_Num_Soli_DSG.Text),
            fecha: DateValue(txt_Fecha_DSG.Text),
            solicitante: txt_Solicitante_DSG.Text,
            user: txt_User_DSG.Text,
            total: Value(
                Sum(
                    Filter(
                        datos_DSG,
                        aprovado,
                        moneda = "USD"
                    ),
                    subtotal
                )
            ),
            totalColones:Value(
                Sum(
                    Filter(
                        datos_DSG,
                        aprovado,
                        moneda <> "USD"
                    ),
                    subtotal
                )
            ),
            estado: "Gerencia",
            comentario: txt_Motivo_DSG_1.Text
        }
    );
    ForAll(
        Filter(
            datos_DSG,
            aprovado
        ),
        Collect(
            Detalle_Solicitud_Compras,
            {
                soli_num: Upper(txt_Num_Soli_DSG.Text),
                item: ThisRecord.item,
                descripcion: ThisRecord.description,
                linea: ThisRecord.req_line
            }
        )
    );
    Reset(txt_Num_Soli_DSG);
    UpdateContext({showContainer: false});
    Reset(txt_Motivo_DSG_1);
    UpdateContext({Guardando: false});
    Back(),
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Tipo: 0,
                Texto: "La solicitud seleccionada ya fue enviada"
            }
        }
    )
);

If(
    IsBlank(
        LookUp(
            Solicitud_Compras,
            soli_num = txt_Num_Soli_DSG.Text
        )
    ),
    DisplayMode.Edit,
    DisplayMode.Disabled
)
